<?php
require_once __DIR__.'/includes/auth.php';$u=require_login();$id=(int)($_GET['id']??0);$q=db()->prepare("SELECT r.*,cu.name customer_name,c.name category_name,s.name service_name,p.name provider_name,b.name business_name FROM service_requests r JOIN users cu ON cu.id=r.customer_id JOIN categories c ON c.id=r.category_id LEFT JOIN services s ON s.id=r.service_id LEFT JOIN users p ON p.id=r.provider_id LEFT JOIN users b ON b.id=r.business_id WHERE r.id=?");$q->execute([$id]);$r=$q->fetch();if(!$r){http_response_code(404);include __DIR__.'/404.php';exit;}
$isCustomer=$u['role']==='customer'&&(int)$r['customer_id']===(int)$u['id'];$isTarget=($u['role']==='provider'&&(int)$r['provider_id']===(int)$u['id'])||($u['role']==='business'&&(int)$r['business_id']===(int)$u['id']);$canClaim=in_array($u['role'],['provider','business'],true)&&$r['request_type']==='requirement'&&$r['status']==='pending'&&!$r['provider_id']&&!$r['business_id'];if($canClaim){$z=db()->prepare("SELECT COUNT(*) FROM provider_services WHERE provider_user_id=? AND service_id=? AND is_active=1");$z->execute([$u['id'],$r['service_id']]);$canClaim=(bool)$z->fetchColumn();}
if(!$isCustomer&&!$isTarget&&!$canClaim&&$u['role']!=='admin'){http_response_code(403);include __DIR__.'/403.php';exit;}
$allowed=[];if($isCustomer&&in_array($r['status'],['pending','accepted'],true))$allowed=['cancelled'];if($isTarget){$allowed=match($r['status']){'pending'=>['accepted','rejected'],'accepted'=>['in_progress','cancelled'],'in_progress'=>['completed','cancelled'],default=>[]};}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';$pdo=db();if($action==='claim'&&$canClaim){$pdo->beginTransaction();try{$lock=$pdo->prepare("SELECT status,provider_id,business_id FROM service_requests WHERE id=? FOR UPDATE");$lock->execute([$id]);$cur=$lock->fetch();if(!$cur||$cur['status']!=='pending'||$cur['provider_id']||$cur['business_id'])throw new RuntimeException();$field=$u['role']==='provider'?'provider_id':'business_id';$pdo->prepare("UPDATE service_requests SET $field=? WHERE id=?")->execute([$u['id'],$id]);$pdo->prepare("INSERT INTO request_status_history(request_id,status,changed_by,note) VALUES(?,'pending',?,'Requirement claimed; awaiting provider acceptance')")->execute([$id,$u['id']]);$pdo->prepare("INSERT INTO notifications(user_id,type,title,message,link) VALUES(?,'requirement_claimed','Provider responded to your requirement',?,?)")->execute([$r['customer_id'],$u['name'].' responded to your requirement.','request-details.php?id='.$id]);$pdo->commit();flash('success','Requirement assigned to you. You can now accept or reject it.');redirect(($u['role']==='business'?'business':'provider').'/requests.php');}catch(Throwable $e){$pdo->rollBack();flash('error','This requirement is no longer available.');redirect('provider/available-requirements.php');}}
if($action==='status'){$new=$_POST['status']??'';if(!in_array($new,$allowed,true)){flash('error','That status change is not allowed.');redirect('request-details.php?id='.$id);} $pdo->beginTransaction();try{$pdo->prepare("UPDATE service_requests SET status=? WHERE id=?")->execute([$new,$id]);$note=trim((string)($_POST['note']??''));if(text_length($note)>500)throw new RuntimeException('Status note is too long.');$pdo->prepare("INSERT INTO request_status_history(request_id,status,changed_by,note) VALUES(?,?,?,?)")->execute([$id,$new,$u['id'],$note?:null]);$notify=$isCustomer?($r['provider_id']?:$r['business_id']):$r['customer_id'];if($notify)$pdo->prepare("INSERT INTO notifications(user_id,type,title,message,link) VALUES(?,'request_status','Service request updated',?,?)")->execute([$notify,'Request #'.$id.' is now '.ucwords(str_replace('_',' ',$new)).'.','request-details.php?id='.$id]);$pdo->commit();flash('success','Request status updated.');redirect(($u['role']==='business'?'business':'provider').'/requests.php');}catch(Throwable $e){$pdo->rollBack();flash('error','Could not update the request.');redirect('request-details.php?id='.$id);}}
}
$h=db()->prepare("SELECT h.*,u.name changed_by_name FROM request_status_history h JOIN users u ON u.id=h.changed_by WHERE h.request_id=? ORDER BY h.created_at ASC,h.id ASC");$h->execute([$id]);$history=$h->fetchAll();$pageTitle='Request #'.$id.' — LocalConnect';require __DIR__.'/includes/header.php';?>
<div class="container py-5" style="max-width:1000px"><?php if($m=flash('success')):?><div class="alert alert-success"><?=e($m)?></div><?php endif;?><?php if($m=flash('error')):?><div class="alert alert-danger"><?=e($m)?></div><?php endif;?><div class="soft-card p-4 mb-4"><div class="d-flex justify-content-between gap-3 flex-wrap"><div><div class="text-muted small">Request #<?=$id?> · <?=e($r['request_type']==='requirement'?'Open Requirement':'Direct Request')?></div><h1 class="h3 fw-bold mb-1"><?=e($r['title'])?></h1><div class="text-muted"><?=e($r['service_name']?:$r['category_name'])?> · <?=e($r['location_text'])?></div></div><span class="badge request-status status-<?=e($r['status'])?> align-self-start"><?=e(ucwords(str_replace('_',' ',$r['status'])))?></span></div><hr><p><?=nl2br(e($r['description']))?></p><div class="row small"><div class="col-md-4 mb-2"><strong>Customer:</strong> <?=e($r['customer_name'])?></div><div class="col-md-4 mb-2"><strong>Preferred:</strong> <?=e($r['preferred_date']?:'Flexible')?> <?=e($r['preferred_time']?substr($r['preferred_time'],0,5):'')?></div><div class="col-md-4 mb-2"><strong>Budget:</strong> <?=($r['budget_min']!==null?'₹'.number_format((float)$r['budget_min']):'Not specified')?><?=($r['budget_max']!==null?' – ₹'.number_format((float)$r['budget_max']):'')?></div></div><?php if($r['additional_notes']):?><div class="alert alert-light mt-3 mb-0"><strong>Notes:</strong> <?=e($r['additional_notes'])?></div><?php endif;?></div>
<?php if($canClaim):?><div class="soft-card p-4 mb-4"><h2 class="h5">Respond to this requirement</h2><p class="text-muted">Claiming assigns this open requirement to your account. You can then accept or reject it.</p><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="claim"><button class="btn btn-primary">Respond to Requirement</button></form></div><?php endif;?>
<?php if($allowed):?><div class="soft-card p-4 mb-4"><h2 class="h5">Update request</h2><form method="post" class="row g-2 align-items-end"><?=csrf_field()?><input type="hidden" name="action" value="status"><div class="col-md-4"><label class="form-label">New status</label><select name="status" class="form-select" required><?php foreach($allowed as $a):?><option value="<?=e($a)?>"><?=e(ucwords(str_replace('_',' ',$a)))?></option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label">Note (optional)</label><input name="note" maxlength="500" class="form-control"></div><div class="col-md-3"><button class="btn btn-primary w-100">Update Status</button></div></form></div><?php endif;?>
<?php if($isCustomer&&$r['status']==='completed'):?><div class="soft-card p-4 mb-4"><h2 class="h5">Service completed</h2><p class="text-muted">You can now rate and review this provider.</p><a class="btn btn-primary" href="<?=e(base_url('reviews.php'))?>">Write a Review</a></div><?php endif;?><div class="soft-card p-4"><h2 class="h5 mb-4">Status History</h2><div class="timeline"><?php foreach($history as $x):?><div class="timeline-item"><div class="fw-semibold"><?=e(ucwords(str_replace('_',' ',$x['status'])))?></div><div class="small text-muted"><?=e($x['changed_by_name'])?> · <?=e(date('d M Y, h:i A',strtotime($x['created_at'])))?></div><?php if($x['note']):?><div class="small mt-1"><?=e($x['note'])?></div><?php endif;?></div><?php endforeach;?></div></div></div><?php require __DIR__.'/includes/footer.php';?>